-- Convergência final do contrato físico governamental de Compras.
-- Contratos UUID são separados previamente pelos scripts de compatibilidade 070/071.

create table if not exists sigov.compras_fornecedor_cotacao (
 id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null,
 pesquisa_item_id bigint not null references sigov.compras_pesquisa_preco_item(id) on delete cascade,
 fornecedor_id bigint not null, fonte varchar(40) not null, valor_unitario numeric(18,4) not null,
 coletado_em date not null, discrepante boolean not null default false, justificativa_discrepancia text,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by bigint not null, updated_by bigint not null,
 check(valor_unitario>=0), check(not discrepante or nullif(btrim(justificativa_discrepancia),'') is not null), unique(pesquisa_item_id,fornecedor_id,fonte));
create table if not exists sigov.compras_proposta (
 id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null,
 licitacao_id bigint not null references sigov.compras_licitacao(id), lote_id bigint references sigov.compras_licitacao_lote(id),
 item_id bigint references sigov.compras_licitacao_item(id), fornecedor_id bigint not null, valor numeric(18,4) not null,
 status varchar(20) not null default 'recebida', ordem_classificacao integer, justificativa_desclassificacao text,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by bigint not null, updated_by bigint not null,
 check(valor>=0), check((lote_id is not null)<>(item_id is not null)), check(status in('recebida','classificada','desclassificada','vencedora')),
 check(status<>'desclassificada' or nullif(btrim(justificativa_desclassificacao),'') is not null));
create table if not exists sigov.compras_habilitacao (
 id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null,
 licitacao_id bigint not null references sigov.compras_licitacao(id), fornecedor_id bigint not null, status varchar(20) not null,
 justificativa text, responsavel_id bigint not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by bigint not null, updated_by bigint not null,
 check(status in('pendente','habilitado','inabilitado')), check(status<>'inabilitado' or nullif(btrim(justificativa),'') is not null));
create table if not exists sigov.compras_recurso (
 id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null,
 licitacao_id bigint not null references sigov.compras_licitacao(id), fornecedor_id bigint not null, motivo text not null,
 prazo_final timestamptz not null, decisao varchar(20), fundamentacao text, responsavel_id bigint,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by bigint not null, updated_by bigint not null,
 check(decisao is null or decisao in('deferido','indeferido')), check(decisao is null or (nullif(btrim(fundamentacao),'') is not null and responsavel_id is not null)));
create table if not exists sigov.contrato_administrativo (
 id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, esfera_governo varchar(10) not null,
 licitacao_id bigint references sigov.compras_licitacao(id), ata_id bigint, fornecedor_id bigint not null, orgao_id bigint,
 unidade_gestora_id bigint not null, unidade_executora_id bigint, numero varchar(80) not null, objeto text not null,
 valor_inicial numeric(18,4) not null, saldo numeric(18,4) not null, inicio_vigencia date not null, fim_vigencia date not null,
 status varchar(20) not null default 'vigente', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by bigint not null, updated_by bigint not null,
 check(esfera_governo in('municipal','estadual','federal')), check(valor_inicial>=0 and saldo>=0 and saldo<=valor_inicial),
 check(fim_vigencia>=inicio_vigencia), check(status in('rascunho','vigente','suspenso','encerrado','rescindido','cancelado')), unique(tenant_id,entidade_id,numero));
create table if not exists sigov.contrato_sancao (
 id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null,
 contrato_id bigint not null references sigov.contrato_administrativo(id), fornecedor_id bigint not null, motivo text not null,
 fundamento text not null, inicio_em date not null, fim_em date not null, responsavel_id bigint not null, status varchar(20) not null default 'aberta',
 created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by bigint not null, updated_by bigint not null,
 check(fim_em>=inicio_em), check(status in('aberta','em_recurso','aplicada','revogada','encerrada')));

do $$
declare t text; col text; actual text; rows_count bigint; fk record; fk_name text;
begin
 if to_regclass('sigov.compras_fornecedor') is null then raise exception 'Contrato físico inválido: tabela=sigov.compras_fornecedor coluna=id tipo_atual=ausente tipo_esperado=bigint'; end if;
 select a.atttypid::regtype::text into actual from pg_attribute a where a.attrelid='sigov.compras_fornecedor'::regclass and a.attname='id' and not a.attisdropped;
 if actual<>'bigint' then raise exception 'Contrato físico inválido: tabela=sigov.compras_fornecedor coluna=id tipo_atual=% tipo_esperado=bigint; separe primeiro o domínio UUID',coalesce(actual,'ausente'); end if;
 foreach t in array array['compras_fornecedor_cotacao','compras_proposta','compras_habilitacao','compras_recurso','contrato_administrativo','contrato_sancao'] loop
  foreach col in array array['tenant_id','entidade_id','fornecedor_id'] loop
   select a.atttypid::regtype::text into actual from pg_attribute a where a.attrelid=to_regclass('sigov.'||t) and a.attname=col and not a.attisdropped;
   if actual is distinct from 'bigint' then
    execute format('select count(*) from sigov.%I',t) into rows_count;
    if rows_count<>0 then raise exception 'Migração automática bloqueada: tabela=sigov.% coluna=% tipo_atual=% tipo_esperado=bigint registros=%',t,col,coalesce(actual,'ausente'),rows_count; end if;
    for fk in select c.conname from pg_constraint c where c.conrelid=to_regclass('sigov.'||t) and c.contype='f' and (select a.attnum from pg_attribute a where a.attrelid=c.conrelid and a.attname=col)=any(c.conkey)
    loop execute format('alter table sigov.%I drop constraint %I',t,fk.conname); end loop;
    execute format('alter table sigov.%I alter column %I type bigint using null::bigint',t,col);
   end if;
  end loop;
  for fk in select c.conname from pg_constraint c where c.conrelid=to_regclass('sigov.'||t) and c.contype='f'
    and c.conkey=array[(select a.attnum from pg_attribute a where a.attrelid=c.conrelid and a.attname='fornecedor_id')]::smallint[]
    and (c.confrelid<>'sigov.compras_fornecedor'::regclass or c.confkey<>array[(select a.attnum from pg_attribute a where a.attrelid='sigov.compras_fornecedor'::regclass and a.attname='id')]::smallint[])
  loop execute format('alter table sigov.%I drop constraint %I',t,fk.conname); end loop;
  fk_name='fk_'||t||'_fornecedor';
  if not exists(select 1 from pg_constraint c where c.conrelid=to_regclass('sigov.'||t) and c.contype='f' and c.confrelid='sigov.compras_fornecedor'::regclass
    and c.conkey=array[(select a.attnum from pg_attribute a where a.attrelid=c.conrelid and a.attname='fornecedor_id')]::smallint[]
    and c.confkey=array[(select a.attnum from pg_attribute a where a.attrelid=c.confrelid and a.attname='id')]::smallint[]) then
   execute format('alter table sigov.%I add constraint %I foreign key(fornecedor_id) references sigov.compras_fornecedor(id) not valid',t,fk_name);
  else select c.conname into fk_name from pg_constraint c where c.conrelid=to_regclass('sigov.'||t) and c.contype='f' and c.confrelid='sigov.compras_fornecedor'::regclass
    and c.conkey=array[(select a.attnum from pg_attribute a where a.attrelid=c.conrelid and a.attname='fornecedor_id')]::smallint[];
  end if;
  execute format('alter table sigov.%I validate constraint %I',t,fk_name);
 end loop;
end $$;

alter table sigov.contrato_fiscal add column if not exists ativo boolean;
do $$ declare actual text; begin select a.atttypid::regtype::text into actual from pg_attribute a where a.attrelid='sigov.contrato_fiscal'::regclass and a.attname='ativo' and not a.attisdropped;
 if actual<>'boolean' then raise exception 'Contrato físico inválido: tabela=sigov.contrato_fiscal coluna=ativo tipo_atual=% tipo_esperado=boolean',coalesce(actual,'ausente'); end if; end $$;
update sigov.contrato_fiscal set ativo=true where ativo is null;
alter table sigov.contrato_fiscal alter column ativo set default true, alter column ativo set not null;
do $$ declare definition text; associated boolean; begin
 if to_regclass('sigov.ix_contrato_fiscal_ativo') is not null then
  select pg_get_indexdef(i.indexrelid),exists(select 1 from pg_constraint c where c.conindid=i.indexrelid) into definition,associated
  from pg_index i where i.indexrelid='sigov.ix_contrato_fiscal_ativo'::regclass;
  if definition is distinct from 'CREATE INDEX ix_contrato_fiscal_ativo ON sigov.contrato_fiscal USING btree (tenant_id, contrato_id, ativo)' then
   if associated then raise exception 'Índice incorreto associado a constraint: tabela=sigov.contrato_fiscal indice=ix_contrato_fiscal_ativo obtido=% esperado=(tenant_id, contrato_id, ativo)',definition; end if;
   drop index sigov.ix_contrato_fiscal_ativo;
  end if;
 end if;
end $$;
create index if not exists ix_contrato_fiscal_ativo on sigov.contrato_fiscal(tenant_id,contrato_id,ativo);
